	@Test
	void plannerChoosesTheBranchedCentreOfAPath() {
		TestGraph graph = pathGraph();
		RowState row = row(graph.source(), "a", "b", "c", "d", "e");
		MultiJoinPlan join = join(
				pattern(0, P1, 1),
				pattern(1, P2, 2),
				pattern(2, P3, 3),
				pattern(3, P4, 4));

		LmdbNativePackedFtree.Plan plan = LmdbNativePackedFtree.Planner.plan(join, row,
				new int[] { 0, 1, 2, 3, 4 });

		assertNotNull(plan);
		assertEquals(2, plan.root.slot, "the middle variable must root the minimum-size f-tree");
		assertEquals(2, plan.root.children.length);
		LmdbNativePackedFtree.NodePlan b = plan.bySlot.get(1);
		LmdbNativePackedFtree.NodePlan a = plan.bySlot.get(0);
		LmdbNativePackedFtree.NodePlan d = plan.bySlot.get(3);
		LmdbNativePackedFtree.NodePlan e = plan.bySlot.get(4);
		assertSame(plan.root, b.parent);
		assertSame(b, a.parent);
		assertSame(plan.root, d.parent);
		assertSame(d, e.parent);
	}

