	@Test
	void cascadeAggregatesToTheRootAndScattersIntoTheOtherArm() {
		LmdbNativePackedFtree.Plan plan = manualPathPlan();
		LmdbNativePackedFtree.Chunk chunk = manualPathChunk(plan);
		LmdbNativePackedFtree.NodePlan e = plan.bySlot.get(4);
		LmdbNativePackedFtree.NodeData eData = chunk.data[e.ordinal];

		// Remove every e value. Both d bindings become empty, which invalidates c; c then clears the complete b/a arm.
		eData.state.clearRange(0, eData.size);
		chunk.cascade.propagateFrom(e);

		for (LmdbNativePackedFtree.NodeData data : chunk.data) {
			assertEquals(0, data.state.cardinality(0, data.size));
			assertEquals(0, data.state.invalidatedSize, "cascade deltas are single-use");
		}
	}

	@Test
	void sharedStatePropagatesWithoutOffsetLookups() {
		LmdbNativePackedFtree.NodePlan root = new LmdbNativePackedFtree.NodePlan(0, 0);
		LmdbNativePackedFtree.NodePlan child = new LmdbNativePackedFtree.NodePlan(1, 1);
		LmdbNativePackedFtree.NodePlan leaf = new LmdbNativePackedFtree.NodePlan(2, 2);
		child.parent = root;
		leaf.parent = child;
		root.children = new LmdbNativePackedFtree.NodePlan[] { child };
		child.children = new LmdbNativePackedFtree.NodePlan[] { leaf };
		LmdbNativePackedFtree.Plan plan = new LmdbNativePackedFtree.Plan(null, root,
				new LmdbNativePackedFtree.NodePlan[] { root, child, leaf },
				new LmdbNativePackedFtree.ConstantPattern[0],
				7L, new int[0], new long[0], 0D);
		LmdbNativePackedFtree.Chunk chunk = new LmdbNativePackedFtree.Chunk(plan, 1L);
		LmdbNativePackedFtree.NodeData rootData = chunk.data[0];
		rootData.ensureCapacity(2);
		rootData.setValue(0, 1L);
		rootData.setValue(1, 2L);
		rootData.size = 2;
		rootData.state.reset(2);
		LmdbNativePackedFtree.NodeData childData = chunk.data[1];
		childData.ensureCapacity(2);
		childData.setValue(0, 10L);
		childData.setValue(1, 20L);
		childData.size = 2;
		childData.state = rootData.state;
		childData.sharedWithParent = true;
		LmdbNativePackedFtree.NodeData leafData = chunk.data[2];
		leafData.ensureCapacity(2);
		leafData.setValue(0, 100L);
		leafData.setValue(1, 200L);
		leafData.size = 2;
		leafData.offsets = new int[] { 0, 1, 2 };
		leafData.state.reset(2);

		rootData.state.clear(0);
		chunk.cascade.propagateFrom(root);

		assertFalse(rootData.state.isSet(0));
		assertFalse(childData.state.isSet(0));
		assertFalse(leafData.state.isSet(0));
		assertTrue(leafData.state.isSet(1));
	}

	@Test
	void sharedStateAlignmentHandlesInactiveParentGapsAndChunkReuse() {
		LmdbNativePackedFtree.NodePlan root = new LmdbNativePackedFtree.NodePlan(0, 0);
		LmdbNativePackedFtree.NodePlan child = new LmdbNativePackedFtree.NodePlan(1, 1);
		child.parent = root;
		root.children = new LmdbNativePackedFtree.NodePlan[] { child };
		LmdbNativePackedFtree.Plan plan = new LmdbNativePackedFtree.Plan(null, root,
				new LmdbNativePackedFtree.NodePlan[] { root, child },
				new LmdbNativePackedFtree.ConstantPattern[0], 3L, new int[0], new long[0], 0D);
		LmdbNativePackedFtree.Chunk chunk = new LmdbNativePackedFtree.Chunk(plan, 1L);
		LmdbNativePackedFtree.NodeData parent = chunk.data[0];
		fill(parent, new long[] { 1, 2, 3 }, null);
		parent.state.clear(0);
		LmdbNativePackedFtree.NodeData out = chunk.data[1];
		fill(out, new long[] { 20, 30 }, new int[] { 0, 0, 1, 2 });
		out.ensureWeights();
		out.weights[0] = 2L;
		out.weights[1] = 3L;

		out.convertToShared(parent);
		assertSame(parent.state, out.state);
		assertEquals(20L, out.value(1));
		assertEquals(30L, out.value(2));
		assertEquals(2L, out.weight(1));
		assertEquals(3L, out.weight(2));

		chunk.reset();
		assertSame(out.ownedState, out.state);
		assertFalse(out.sharedWithParent);
		assertEquals(0, out.size);
		assertEquals(1L, out.weight(1), "recycled vectors must not retain multiplicity from the previous chunk");
	}

	@Test
	void bitmapOperationsAreCorrectAcrossWordBoundaries() {
		LmdbNativePackedFtree.PackedState state = new LmdbNativePackedFtree.PackedState(192);
		state.reset(192);
		state.clearRange(63, 129);

		assertEquals(126, state.cardinality(0, 192));
		assertTrue(state.isSet(62));
		assertFalse(state.isSet(63));
		assertFalse(state.isSet(64));
		assertFalse(state.isSet(128));
		assertTrue(state.isSet(129));
		assertFalse(state.anySet(63, 129));
		assertTrue(state.anySet(0, 63));
		assertTrue(state.anySet(129, 192));
	}

	@Test
	void highDegreeRunsContinueInFixedWidthBlocks() {
		LmdbNativePackedFtree.NodePlan node = new LmdbNativePackedFtree.NodePlan(0, 0);
		LmdbNativePackedFtree.NodeData data = new LmdbNativePackedFtree.NodeData(node);
		int count = LmdbNativePackedFtree.VECTOR_SIZE * 2 + 17;
		data.ensureCapacity(count);
		for (int i = 0; i < count; i++) {
			data.setValue(i, i * 17L);
		}
		data.size = count;

		assertEquals(3, data.segmentCount());
		assertEquals((LmdbNativePackedFtree.VECTOR_SIZE - 1L) * 17L,
				data.value(LmdbNativePackedFtree.VECTOR_SIZE - 1));
		assertEquals(LmdbNativePackedFtree.VECTOR_SIZE * 17L,
				data.value(LmdbNativePackedFtree.VECTOR_SIZE));
		assertEquals((count - 1L) * 17L, data.value(count - 1));
	}

	@Test
	void generatedTopologyKernelMatchesInterpretedCardinalities() throws Exception {
		LmdbNativePackedFtree.Plan plan = manualPathPlan();
		LmdbNativePackedFtree.Chunk interpreted = manualPathChunk(plan);
		assertEquals(15L, interpreted.computeSubtreeCountsInterpreted());
		long[][] expectedSubtree = copyCounts(interpreted, true);
		long[][] expectedOutside = copyCounts(interpreted, false);

		LmdbNativePackedFtree.Chunk generated = manualPathChunk(plan);
		generated.prepareCountArrays();
		String simpleName = "PackedFtreeGeneratedParity";
		String className = "org.eclipse.rdf4j.sail.lmdb.evaluation.codegen." + simpleName;
		SimpleCompiler compiler = new SimpleCompiler();
		compiler.setSourceVersion(8);
		compiler.setTargetVersion(8);
		compiler.setParentClassLoader(getClass().getClassLoader());
		compiler.cook(LmdbNativePackedFtreeJanino.sourceForTest(plan, simpleName));
		PackedFtreeKernel kernel = (PackedFtreeKernel) compiler.getClassLoader()
				.loadClass(className)
				.getDeclaredConstructor()
				.newInstance();
		PackedFtreeContext packed = generated.packedContext();
		kernel.bind(new KernelContext(new NativeAdjacency[0], new long[0], new long[0], new long[0][])
				.withPackedFtree(packed));
		assertEquals(0, kernel.fill(new long[0], 0));
		assertEquals(15L, packed.totalRows);
		for (int i = 0; i < plan.nodes.length; i++) {
			assertArrayEquals(expectedSubtree[i], Arrays.copyOf(packed.subtreeCounts[i], generated.data[i].size));
			assertArrayEquals(expectedOutside[i], Arrays.copyOf(packed.outsideCounts[i], generated.data[i].size));
		}
	}

	@Test
	void generatedTopologyKernelHandlesTheMaximumWidthStar() throws Exception {
		int childCount = Long.SIZE - 1;
		LmdbNativePackedFtree.NodePlan root = new LmdbNativePackedFtree.NodePlan(0, 0);
		LmdbNativePackedFtree.NodePlan[] nodes = new LmdbNativePackedFtree.NodePlan[childCount + 1];
		LmdbNativePackedFtree.NodePlan[] children = new LmdbNativePackedFtree.NodePlan[childCount];
		nodes[0] = root;
		for (int i = 0; i < childCount; i++) {
			LmdbNativePackedFtree.NodePlan child = new LmdbNativePackedFtree.NodePlan(i + 1, i + 1);
			child.parent = root;
			nodes[i + 1] = child;
			children[i] = child;
		}
		root.children = children;
		LmdbNativePackedFtree.Plan plan = new LmdbNativePackedFtree.Plan(null, root, nodes,
				new LmdbNativePackedFtree.ConstantPattern[0], -1L, new int[0], new long[0], 0D);
		LmdbNativePackedFtree.Chunk chunk = new LmdbNativePackedFtree.Chunk(plan, 1L);
		fill(chunk.data[0], new long[] { 1L }, null);
		for (int i = 1; i < nodes.length; i++) {
			fill(chunk.data[i], new long[] { 1000L + i }, new int[] { 0, 1 });
		}
		assertEquals(1L, chunk.computeSubtreeCountsInterpreted());

		String simpleName = "PackedFtreeMaximumWidthStar";
		String className = "org.eclipse.rdf4j.sail.lmdb.evaluation.codegen." + simpleName;
		SimpleCompiler compiler = new SimpleCompiler();
		compiler.setSourceVersion(8);
		compiler.setTargetVersion(8);
		compiler.setParentClassLoader(PackedFtreeKernel.class.getClassLoader());
		compiler.cook(LmdbNativePackedFtreeJanino.sourceForTest(plan, simpleName));
		PackedFtreeKernel kernel = (PackedFtreeKernel) compiler.getClassLoader()
				.loadClass(className)
				.getDeclaredConstructor()
				.newInstance();
		LmdbNativePackedFtree.Chunk generated = new LmdbNativePackedFtree.Chunk(plan, 1L);
		fill(generated.data[0], new long[] { 1L }, null);
		for (int i = 1; i < nodes.length; i++) {
			fill(generated.data[i], new long[] { 1000L + i }, new int[] { 0, 1 });
		}
		generated.prepareCountArrays();
		PackedFtreeContext packed = generated.packedContext();
		kernel.bind(new KernelContext(new NativeAdjacency[0], new long[0], new long[0], new long[0][])
				.withPackedFtree(packed));
		assertEquals(0, kernel.fill(new long[0], 0));
		assertEquals(1L, packed.totalRows);
	}

	@Test
	void optionalUnionAndBindRetainPackedSiblingFactors() throws Exception {
		TestGraph graph = pathGraph();
		graph.borrow = true;
		RowState row = row(graph.source(), "a", "b", "c", "d", "e", "alias", "label");
		SlotPlan path = join(pattern(0, P1, 1), pattern(1, P2, 2), pattern(2, P3, 3), pattern(3, P4, 4));
		SlotPlan bound = new ExtensionPlan(path, new CopyBinding[] { CopyBinding.slot(5, 0),
				CopyBinding.constant(6, 777L) });
		SlotPlan optional = new LeftJoinPlan(new UnionPlan(bound, bound),
				new FilterPlan(SingletonPlan.INSTANCE, ignored -> false, 0L));
		long total = 0L;
		try (RowCursor cursor = LmdbNativeFactorRows.asRows(LmdbNativeFactorAlgebra.open(optional, row), row)) {
			while (cursor.next()) {
				assertEquals(row.slots[0], row.slots[5]);
				assertEquals(777L, row.slots[6]);
				total = Math.addExact(total, ((FactorizedRowCursor) cursor).multiplicity());
			}
		}
		assertEquals(30L, total, "UNION adds two 15-row paths; a rejected OPTIONAL emits each left mapping once");
		for (long value : row.slots)
			assertEquals(LmdbNativeAggregateCompiler.UNKNOWN, value);
	}

	@Test
	void boundPackedLeafKeepsEntryBindingsAndClosesEarly() throws Exception {
		TestGraph graph = pathGraph();
		graph.borrow = true;
		RowState row = row(graph.source(), "a", "b", "c", "d", "e");
		assertTrue(row.bind(0, 2L));
		int entryMark = row.mark();
		SlotPlan path = join(pattern(0, P1, 1), pattern(1, P2, 2), pattern(2, P3, 3), pattern(3, P4, 4));
		SlotPlan union = new UnionPlan(path, path);
		try (RowCursor cursor = LmdbNativeFactorRows.asRows(LmdbNativeFactorAlgebra.open(union, row), row)) {
			assertTrue(cursor.next());
			assertEquals(2L, row.slots[0]);
		}
		assertEquals(entryMark, row.mark());
		assertEquals(2L, row.slots[0]);
		long count = 0L;
		try (RowCursor cursor = LmdbNativeFactorRows.asRows(LmdbNativeFactorAlgebra.open(union, row), row)) {
			while (cursor.next())
				count += ((FactorizedRowCursor) cursor).multiplicity();
		}
		assertEquals(10L, count);
	}

	@Test
	void independentAggregateReadersKeepOnePackedProducerAndOutsideWeights() throws Exception {
		TestGraph graph = pathGraph();
		graph.borrow = true;
		RowState row = row(graph.source(), "a", "b", "c", "d", "e", "label");
		SlotPlan path = join(pattern(0, P1, 1), pattern(1, P2, 2), pattern(2, P3, 3), pattern(3, P4, 4));
		SlotPlan plan = new ExtensionPlan(new UnionPlan(path, path),
				new CopyBinding[] { CopyBinding.constant(5, 777L) });
		long[] weights = new long[3];
		try (NativeFactorProjections projections = plan.openProjections(row,
				new int[][] { { 2 }, { 2, 0 }, { 2, 4 } }, new boolean[] { false, true, true })) {
			assertNotNull(projections);
			while (projections.nextBatch()) {
				for (int p = 0; p < weights.length; p++) {
					while (projections.next(p)) {
						assertEquals(20L, projections.value(2));
						weights[p] += projections.multiplicity();
					}
				}
			}
		}
		assertTrue(weights[0] > 0L);
		assertEquals(30L, weights[1]);
		assertEquals(30L, weights[2]);
	}

	private static long[][] copyCounts(LmdbNativePackedFtree.Chunk chunk, boolean subtree) {
		long[][] result = new long[chunk.data.length][];
		for (int i = 0; i < result.length; i++) {
			long[] source = subtree ? chunk.data[i].subtreeCounts : chunk.data[i].outsideCounts;
			result[i] = Arrays.copyOf(source, chunk.data[i].size);
		}
		return result;
	}

	private static int physicalValues(LmdbNativePackedFtree.Chunk chunk) {
		int total = 0;
		for (LmdbNativePackedFtree.NodeData data : chunk.data) {
			total += data.size;
		}
		return total;
	}

	@Test
	void singlePatternLeafHasARealPackedRuntimeWithoutFutureOutputs() throws Exception {
		TestGraph graph = new TestGraph();
		graph.add(P1, 1L, 42L, 0L);
		graph.add(P1, 2L, 42L, 0L);
		RowState row = row(graph.source(), "s", "future", "alsoFuture");
		PatternPlan pattern = new PatternPlan(Term.slot(0), Term.constant(P1), Term.constant(42L),
				Term.unbound(), ContextConstraint.UNRESTRICTED, false, 2D);
		assertNull(LmdbNativePackedFtree.Planner.plan(join(pattern), row, new int[] { 0, 1, 2 }),
				"unavailable retained names are not proven physical outputs");
		assertNotNull(LmdbNativePackedFtree.Planner.plan(join(pattern), row, new int[] { 0 }));
		List<Long> subjects = new ArrayList<>();
		try (LmdbNativeFactorCursor cursor = LmdbNativePackedFtree.openLeaf(join(pattern), row)) {
			assertNotNull(cursor);
			assertTrue(cursor instanceof LmdbNativePackedFtree.GroupedRowCursor,
					"the existing leaf must own the production packed runtime, not a scalar adapter");
			while (cursor.next()) {
				subjects.add(row.slots[0]);
				assertEquals(0L, row.boundMask() & 6L);
			}
		}
		assertEquals(List.of(1L, 2L), subjects);
		assertEquals(0L, row.boundMask());
	}

