	private static MultiJoinPlan join(PatternPlan... patterns) {
		return new MultiJoinPlan(patterns, new MaskedFilter[0]);
	}

	private static PatternPlan pattern(int subjectSlot, long predicate, int objectSlot) {
		return new PatternPlan(Term.slot(subjectSlot), Term.constant(predicate), Term.slot(objectSlot), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 2D);
	}

	private static RowState row(NativeLmdbQuerySource source, String... names) {
		Map<String, Integer> slots = new LinkedHashMap<>();
		for (int i = 0; i < names.length; i++) {
			slots.put(names[i], i);
		}
		NativeSlotLayout layout = new NativeSlotLayout(slots, null);
		layout.freeze(List.of(names));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertTrue(NativeRowSeeder.seed(row.slots, layout, EmptyBindingSet.getInstance(), source));
		return row;
	}

	private static TestGraph pathGraph() {
		TestGraph graph = new TestGraph();
		graph.add(P1, 1, 11, 0);
		graph.add(P1, 2, 11, 0);
		graph.add(P1, 3, 12, 0);
		graph.add(P2, 11, 20, 0);
		graph.add(P2, 12, 20, 0);
		graph.add(P3, 20, 31, 0);
		graph.add(P3, 20, 32, 0);
		graph.add(P4, 31, 41, 0);
		graph.add(P4, 31, 42, 0);
		graph.add(P4, 32, 43, 0);
		graph.add(P4, 32, 44, 0);
		graph.add(P4, 32, 45, 0);
		return graph;
	}

	private static LmdbNativePackedFtree.Plan manualPathPlan() {
		return manualPathPlan(new int[0], new long[0]);
	}

	private static LmdbNativePackedFtree.Plan manualPathPlan(int[] fixedSlots, long[] fixedValues) {
		LmdbNativePackedFtree.NodePlan c = new LmdbNativePackedFtree.NodePlan(0, 2);
		LmdbNativePackedFtree.NodePlan b = new LmdbNativePackedFtree.NodePlan(1, 1);
		LmdbNativePackedFtree.NodePlan a = new LmdbNativePackedFtree.NodePlan(2, 0);
		LmdbNativePackedFtree.NodePlan d = new LmdbNativePackedFtree.NodePlan(3, 3);
		LmdbNativePackedFtree.NodePlan e = new LmdbNativePackedFtree.NodePlan(4, 4);
		b.parent = c;
		a.parent = b;
		d.parent = c;
		e.parent = d;
		c.children = new LmdbNativePackedFtree.NodePlan[] { b, d };
		b.children = new LmdbNativePackedFtree.NodePlan[] { a };
		d.children = new LmdbNativePackedFtree.NodePlan[] { e };
		return new LmdbNativePackedFtree.Plan(null, c,
				new LmdbNativePackedFtree.NodePlan[] { c, b, a, d, e },
				new LmdbNativePackedFtree.ConstantPattern[0], 31L, fixedSlots, fixedValues, 0D);
	}

	/**
	 * The janino kernel cache is process-wide ({@code LmdbNativeJaninoCodegen}), so a shape key or generated source
	 * that embedded a store id or an entry-binding value would silently evaluate one plan against another plan's data.
	 * Two plans that differ only in their id-bearing inputs must therefore produce the same key and source.
	 */
	@Test
	void topologyKeyAndGeneratedSourceAreIdFree() {
		LmdbNativePackedFtree.Plan first = manualPathPlan(new int[0], new long[0]);
		LmdbNativePackedFtree.Plan second = manualPathPlan(new int[] { 7 }, new long[] { 987654321L });
		assertEquals(LmdbNativePackedFtreeJanino.topologyKeyForTest(first),
				LmdbNativePackedFtreeJanino.topologyKeyForTest(second));
		assertEquals(LmdbNativePackedFtreeJanino.sourceForTest(first, "IdFreeProbe"),
				LmdbNativePackedFtreeJanino.sourceForTest(second, "IdFreeProbe"));
	}

	private static LmdbNativePackedFtree.Chunk manualPathChunk(LmdbNativePackedFtree.Plan plan) {
		LmdbNativePackedFtree.Chunk chunk = new LmdbNativePackedFtree.Chunk(plan, 1L);
		fill(chunk.data[0], new long[] { 20 }, null);
		fill(chunk.data[1], new long[] { 11, 12 }, new int[] { 0, 2 });
		fill(chunk.data[2], new long[] { 1, 2, 3 }, new int[] { 0, 2, 3 });
		fill(chunk.data[3], new long[] { 31, 32 }, new int[] { 0, 2 });
		fill(chunk.data[4], new long[] { 41, 42, 43, 44, 45 }, new int[] { 0, 2, 5 });
		return chunk;
	}

	private static void fill(LmdbNativePackedFtree.NodeData data, long[] values, int[] offsets) {
		data.ensureCapacity(values.length);
		data.copyValues(values, 0, 0, values.length);
		data.size = values.length;
		data.offsets = offsets;
		data.state.reset(values.length);
	}

	private record AdjacencyKey(long predicate, boolean bySubject) {
	}

	private static final class TestGraph {
		boolean borrow;
		long failExportKey = -1L;
		private final Map<AdjacencyKey, MutableAdjacency> mutable = new HashMap<>();
		private NativeLmdbQuerySource source;

		void add(long predicate, long subject, long object, long context) {
			mutable.computeIfAbsent(new AdjacencyKey(predicate, true), ignored -> new MutableAdjacency())
					.add(subject, object, context);
			mutable.computeIfAbsent(new AdjacencyKey(predicate, false), ignored -> new MutableAdjacency())
					.add(object, subject, context);
		}

		NativeLmdbQuerySource source() {
			if (source != null) {
				return source;
			}
			Map<AdjacencyKey, TestAdjacency> adjacencies = new HashMap<>();
			for (Map.Entry<AdjacencyKey, MutableAdjacency> entry : mutable.entrySet()) {
				adjacencies.put(entry.getKey(), entry.getValue().freeze(this));
			}
			NativeLmdbQuerySource result = mock(NativeLmdbQuerySource.class);
			NativeLmdbQuerySource.NativeProbe probe = mock(NativeLmdbQuerySource.NativeProbe.class);
			try {
				when(result.newProbe()).thenReturn(probe);
				when(probe.adjacency(anyLong(), anyBoolean())).thenAnswer(invocation -> adjacencies
						.get(new AdjacencyKey(invocation.getArgument(0), invocation.getArgument(1))));
			} catch (Exception e) {
				throw new AssertionError(e);
			}
			when(result.idSpace()).thenReturn(result);
			when(result.adjacencyKeyDomainCardinality(anyLong(), anyBoolean())).thenAnswer(invocation -> {
				TestAdjacency adjacency = adjacencies
						.get(new AdjacencyKey(invocation.getArgument(0), invocation.getArgument(1)));
				return adjacency == null ? OptionalLong.empty() : OptionalLong.of(adjacency.keyCount());
			});
			when(result.meanFanOut(anyLong(), anyBoolean())).thenAnswer(invocation -> {
				TestAdjacency adjacency = adjacencies
						.get(new AdjacencyKey(invocation.getArgument(0), invocation.getArgument(1)));
				return adjacency == null ? OptionalDouble.empty() : OptionalDouble.of(adjacency.meanFanOut());
			});
			when(result.exactDegree(anyLong(), anyLong(), anyBoolean())).thenAnswer(invocation -> {
				TestAdjacency adjacency = adjacencies
						.get(new AdjacencyKey(invocation.getArgument(0), invocation.getArgument(2)));
				if (adjacency == null) {
					return OptionalLong.empty();
				}
				long handle = adjacency.find(invocation.getArgument(1));
				return OptionalLong.of(handle > 0 ? adjacency.size(handle) : 0L);
			});
			source = result;
			return result;
		}
	}

	private static final class MutableAdjacency {
		private final Map<Long, List<long[]>> rows = new HashMap<>();

		void add(long key, long neighbor, long context) {
			rows.computeIfAbsent(key, ignored -> new ArrayList<>()).add(new long[] { neighbor, context });
		}

		TestAdjacency freeze(TestGraph owner) {
			return new TestAdjacency(rows, owner);
		}
	}

	private static final class TestAdjacency implements NativeAdjacency {
		private final TestGraph owner;
		private final long[] keys;
		private final long[][] neighbors;
		private final long[][] contexts;
		private final Map<Long, Integer> ordinalByKey = new HashMap<>();
		private final long edgeCount;

		TestAdjacency(Map<Long, List<long[]>> input, TestGraph owner) {
			this.owner = owner;
			keys = input.keySet().stream().mapToLong(Long::longValue).toArray();
			sortUnsigned(keys);
			neighbors = new long[keys.length][];
			contexts = new long[keys.length][];
			long edges = 0L;
			for (int i = 0; i < keys.length; i++) {
				ordinalByKey.put(keys[i], i);
				List<long[]> row = new ArrayList<>(input.get(keys[i]));
				row.sort((left, right) -> {
					int comparison = Long.compareUnsigned(left[0], right[0]);
					return comparison != 0 ? comparison : Long.compareUnsigned(left[1], right[1]);
				});
				neighbors[i] = new long[row.size()];
				contexts[i] = new long[row.size()];
				for (int j = 0; j < row.size(); j++) {
					neighbors[i][j] = row.get(j)[0];
					contexts[i][j] = row.get(j)[1];
				}
				edges += row.size();
			}
			edgeCount = edges;
		}

		double meanFanOut() {
			return keys.length == 0 ? 0D : (double) edgeCount / keys.length;
		}

		@Override
		public BorrowedFactorBatch.Source openFactorSource() {
			return owner.borrow ? new HeapFactorSource(this) : null;
		}

		@Override
		public boolean borrowRun(long handle, BorrowedFactorBatch target, int lane) {
			int row = index(handle);
			if (!owner.borrow || keys[row] == owner.failExportKey)
				return false;
			target.bindHeap(lane, neighbors[row], 0, neighbors[row].length);
			return true;
		}

		@Override
		public long find(long key) {
			Integer ordinal = ordinalByKey.get(key);
			return ordinal == null ? NOT_FOUND : ordinal + 1L;
		}

		@Override
		public long size(long runHandle) {
			return neighbors[index(runHandle)].length;
		}

		@Override
		public long neighborAt(long runHandle, long runOffset) {
			return neighbors[index(runHandle)][Math.toIntExact(runOffset)];
		}

		@Override
		public long contextAt(long runHandle, long runOffset) {
			return contexts[index(runHandle)][Math.toIntExact(runOffset)];
		}

		@Override
		public int copyNeighbors(long runHandle, long runOffset, int length, long[] target, int targetOffset) {
			long[] row = neighbors[index(runHandle)];
			int from = Math.toIntExact(runOffset);
			int count = Math.min(length, row.length - from);
			System.arraycopy(row, from, target, targetOffset, count);
			return count;
		}

		@Override
		public int copyContexts(long runHandle, long runOffset, int length, long[] target, int targetOffset) {
			long[] row = contexts[index(runHandle)];
			int from = Math.toIntExact(runOffset);
			int count = Math.min(length, row.length - from);
			System.arraycopy(row, from, target, targetOffset, count);
			return count;
		}

		@Override
		public long lowerBound(long runHandle, long fromOffset, long neighbor, long context) {
			long[] ns = neighbors[index(runHandle)];
			long[] cs = contexts[index(runHandle)];
			int low = Math.toIntExact(fromOffset);
			int high = ns.length;
			while (low < high) {
				int mid = (low + high) >>> 1;
				int comparison = Long.compareUnsigned(ns[mid], neighbor);
				if (comparison == 0) {
					comparison = Long.compareUnsigned(cs[mid], context);
				}
				if (comparison < 0) {
					low = mid + 1;
				} else {
					high = mid;
				}
			}
			return low;
		}

		@Override
		public boolean runsNeighborOrdered() {
			return true;
		}

		@Override
		public boolean supportsKeyEnumeration() {
			return true;
		}

		@Override
		public long keyCount() {
			return keys.length;
		}

		@Override
		public long keyAt(long keyOrdinal) {
			return keys[Math.toIntExact(keyOrdinal)];
		}

		private int index(long handle) {
			if (handle <= 0 || handle > keys.length) {
				throw new IllegalArgumentException("invalid run handle " + handle);
			}
			return (int) handle - 1;
		}
	}

